-- 2. Substitution rules (upserted by original + substitute)
insert into public.ingredient_substitutions
  (original_ingredient_id, substitute_ingredient_id, ratio_note, context_note, adjustment_note, limitation_note, allergen_note, is_adapted)
select o.id, s.id, v.ratio_note, v.context_note, v.adjustment_note, v.limitation_note, v.allergen_note, v.is_adapted
from (values
  ('gnocchi', 'pasta', 'About 90 g dried pasta for every 250 g gnocchi.', 'Saucy, pasta-style dishes served hot.', 'Boil the pasta for the time on its packet (usually 9-12 minutes) instead of the 2-3 minutes gnocchi needs, keep a splash of the cooking water, then stir it into the sauce as written.', 'Lighter, less pillowy texture than gnocchi.', 'Both usually contain wheat (gluten); some gnocchi and fresh pasta contain egg.', false),
  ('pasta', 'gnocchi', 'About 250 g gnocchi for every 90-100 g dried pasta.', 'Hot pasta dishes with a sauce. Not for pasta salads, soups or bakes.', 'Boil the gnocchi for 2-3 minutes until they float, drain, then toss with the sauce as written.', 'Heavier and softer; serve straight away.', 'Gnocchi usually contain wheat (gluten) and sometimes egg; check the label.', false),
  ('noodles', 'pasta', 'Same dry weight of spaghetti or linguine.', 'Stir-fries and noodle salads. Not for noodle soups.', 'Boil according to the pasta packet (usually 9-11 minutes), rinse briefly, then continue with the recipe.', 'Firmer, less springy texture.', 'Pasta contains wheat (gluten). Rice noodles don''t, so this is not a swap for gluten-free diets.', true),
  ('rice', 'brown rice', 'Same dry weight, with about 25% more water.', 'Rice served alongside or under a dish. Not for risotto, sushi rice, paella or rice pudding.', 'Simmer brown rice for 25-30 minutes (white rice takes 10-12), so start it first. If the recipe uses cooked rice, use cooked brown rice that was cooled quickly, refrigerated and is under 24 hours old.', 'Nuttier and chewier.', 'No change.', false),
  ('quinoa', 'couscous', 'Same dry weight.', 'Grain salads.', 'Instead of simmering, pour over boiling water (about 1.5x the couscous volume), cover for 5 minutes, then fluff with a fork.', 'Softer texture.', 'Couscous contains wheat (gluten); quinoa does not.', false),
  ('tortilla', 'pitta bread', '1 pitta per tortilla.', 'Wraps that are filled and rolled, not quesadillas or tacos.', 'Warm the pitta, split it open and fill it like a pocket.', 'Holds less filling than a wrap.', 'Both usually contain wheat (gluten).', false),
  ('pitta bread', 'tortilla', '1 tortilla per pitta.', 'Filled pittas and pitta pizzas.', 'Use as a wrap and roll it up. For pizzas, bake 3-4 minutes less because tortillas crisp faster.', 'Thinner and crisper.', 'Both usually contain wheat (gluten).', false),
  ('kale', 'spinach', 'Same weight, or a little more (spinach shrinks a lot).', 'Cooked vegetable dishes.', 'Add spinach at the end and cook for only 1-2 minutes until wilted.', 'Softer and milder than kale.', 'No change.', false),
  ('spinach', 'kale', 'Same weight; remove the tough stalks first.', 'Cooked dishes. Not for smoothies or raw salads.', 'Chop finely and cook for 5-8 minutes until tender (spinach only needs 1-2), then continue.', 'Chewier and stronger tasting.', 'No change.', false),
  ('broccoli', 'cauliflower', 'Same weight.', 'Steamed, stir-fried or pasta dishes.', 'Cut into small florets and cook 2-3 minutes longer until just tender.', 'Milder, softer bite.', 'No change.', false),
  ('cauliflower', 'broccoli', 'Same weight.', 'Roasted vegetables.', 'Broccoli roasts faster: check it after about two-thirds of the roasting time.', 'Edges char more quickly.', 'No change.', false),
  ('tomato', 'canned tomatoes', '1 can (400 g) is roughly 4-5 fresh tomatoes.', 'Baked tomato sauces only. Not for salads, sandwiches or fresh toppings.', 'Drain off some of the juice and bake 5 minutes longer so the sauce thickens.', 'Makes a saucier dish without roasted tomato pieces.', 'No change.', false),
  ('canned tomatoes', 'tomato', 'About 500 g fresh tomatoes (5-6) per 400 g can.', 'Cooked tomato sauces, soups and stews.', 'Chop finely and simmer 5-10 minutes longer until saucy, adding a splash of water if it catches.', 'Fresher, lighter sauce.', 'No change.', false),
  ('canned tomatoes', 'passata', 'Same amount (400 g passata per 400 g can).', 'Cooked tomato sauces, soups and stews.', 'Use exactly as the recipe says; the sauce will be smoother, without chunks.', 'Smoother texture.', 'No change.', false),
  ('passata', 'canned tomatoes', 'Same amount (400 g can per 400 g passata).', 'Tomato sauces, soups and pizza bases.', 'For a smooth result, mash or blend the tomatoes and simmer 5 minutes longer. For pizza, drain off the juice and spread thinly.', 'Chunkier texture.', 'No change.', false),
  ('spring onion', 'onion', 'About ¼ small onion for every 2 spring onions.', 'Cooked dishes.', 'Chop the onion very finely and fry it for 2-3 minutes at the start until softened. You lose the fresh green garnish.', 'Sweeter, less fresh flavour.', 'No change.', false),
  ('onion', 'spring onion', '3-4 spring onions per medium onion.', 'Any dish using onion for flavour.', 'Slice finely. Add the white parts where the recipe adds onion and cook them for 2 minutes; stir in the green parts near the end.', 'Milder flavour and less sweetness in long-cooked sauces.', 'No change.', false),
  ('lettuce', 'spinach', 'Same handful of raw baby spinach.', 'Wraps and salads.', 'Use raw baby spinach leaves; no cooking needed.', 'Softer leaves with less crunch.', 'No change.', false),
  ('zucchini', 'eggplant', 'Same weight.', 'Roasted traybakes.', 'Cut into 2 cm cubes and roast 5-10 minutes longer, until soft all the way through.', 'Softer, creamier texture.', 'No change.', false),
  ('eggplant', 'zucchini', 'Same weight.', 'Stews.', 'Zucchini cooks faster: add it about 10 minutes later than the recipe adds the aubergine.', 'Lighter, less silky texture.', 'No change.', false),
  ('sweet potato', 'potato', 'Same weight.', 'Roasted or baked potatoes.', 'Cut regular potato a little smaller and cook 5-10 minutes longer, until tender in the centre.', 'Less sweet.', 'No change.', false),
  ('potato', 'sweet potato', 'Same weight.', 'Roasted, baked or mashed potatoes.', 'Sweet potato cooks faster and burns more easily: check it 5-10 minutes earlier.', 'Sweeter and softer; won''t crisp as much.', 'No change.', false),
  ('frozen peas', 'sweetcorn', 'Same amount of canned (drained) or frozen sweetcorn.', 'Rice and pasta dishes.', 'Add the sweetcorn at the same point as the peas.', 'Sweeter.', 'No change.', false),
  ('chickpeas', 'cannellini beans', 'Same amount (one 400 g can, drained).', 'Soups, stews, curries and mashed fillings. Not for falafel or crispy roasted chickpeas.', 'Cannellini beans are softer: stir them in for the last 5 minutes of cooking, or mash lightly for sandwiches.', 'Creamier and softer.', 'No change.', false),
  ('cannellini beans', 'chickpeas', 'Same amount (one 400 g can, drained).', 'Soups and stews.', 'Simmer for the same time; chickpeas stay firmer.', 'Firmer, nuttier.', 'No change.', false),
  ('black beans', 'kidney beans', 'Same amount of canned beans, drained and rinsed.', 'Mexican-style fillings, bowls and salads. Not for bean burgers.', 'Use canned (already cooked) kidney beans only. Never use raw dried kidney beans, which must be soaked and boiled hard first.', 'Slightly firmer and larger.', 'No change.', false),
  ('kidney beans', 'black beans', 'Same amount of canned beans, drained and rinsed.', 'Chillis.', 'Use exactly as the recipe says.', 'Softer, earthier.', 'No change.', false),
  ('sour cream', 'yogurt', 'Same amount of plain or Greek yogurt.', 'Cold toppings and sauces stirred in off the heat.', 'Stir it in off the heat; yogurt can split if it boils.', 'Tangier and less rich.', 'Both contain milk.', false),
  ('yogurt', 'sour cream', 'Same amount.', 'Savoury toppings and sauces. Not for sweet breakfasts or smoothies.', 'Use as written; thin with a little water or lemon juice if it is too thick to drizzle.', 'Richer and less tangy.', 'Both contain milk.', false),
  ('creme fraiche', 'cream', 'Same amount of cooking cream.', 'Creamy pan sauces.', 'Simmer for 1-2 minutes to thicken slightly, and add a squeeze of lemon for tang if you like.', 'Slightly thinner sauce.', 'Both contain milk.', false),
  ('cream', 'creme fraiche', 'Same amount.', 'Creamy sauces cooked gently.', 'Stir in over low heat and don''t let it boil hard.', 'Tangier.', 'Both contain milk.', false),
  ('parmesan', 'cheese', 'Same weight of finely grated mature cheddar.', 'Grated toppings and stirred-in finishes. Not for carbonara.', 'Grate it finely and season to taste: cheddar is milder and less salty.', 'Milder, less nutty flavour.', 'Both contain milk.', false),
  ('cheese', 'mozzarella', 'Same weight of grated or torn mozzarella.', 'Melted toppings and fillings. Not for cheese sauces.', 'Use exactly where the recipe uses cheese; it melts stringier.', 'Milder flavour.', 'Both contain milk.', false),
  ('mozzarella', 'cheese', 'Same weight of grated cheddar or another melting cheese.', 'Melted toppings. Not for fresh mozzarella salads.', 'Use exactly where the recipe uses mozzarella.', 'Stronger flavour, less stretch.', 'Both contain milk.', false),
  ('milk', 'plant milk', 'Same amount of unsweetened, unflavoured plant milk.', 'Porridge, smoothies, puddings, batters and white sauces.', 'Use exactly as written; sauces and puddings may need a minute longer to thicken.', 'Slightly different taste; sweetened versions make dishes sweeter.', 'Soy milk contains soy; almond and other nut milks contain tree nuts; oat milk may contain gluten. Check the label.', false),
  ('butter', 'olive oil', 'About ¾ of the butter amount in oil (1 tbsp oil per heaped tbsp butter).', 'Frying and finishing. Not for spreads or garlic bread.', 'Heat the oil where the recipe melts the butter.', 'No buttery flavour.', 'Removes milk (butter contains milk).', false),
  ('chicken breast', 'chicken thighs', 'Same weight of boneless, skinless thighs.', 'Pan-fried, baked or air-fried chicken.', 'Thighs need 2-4 minutes longer. Cook until cooked through with no pink and the juices run clear (75°C in the thickest part). Use a separate board and wash your hands after handling raw chicken.', 'Juicier, richer meat.', 'No change.', false),
  ('chicken thighs', 'chicken breast', 'Same weight of boneless, skinless breast.', 'Pan-fried, baked or rice-cooker chicken.', 'Cut into even pieces. Breast dries out faster, but always cook until cooked through with no pink (75°C in the thickest part). Use a separate board and wash your hands after handling raw chicken.', 'Leaner and can dry out if overcooked.', 'No change.', false),
  ('minced beef', 'minced turkey', 'Same weight.', 'Bolognese, chilli and cottage pie. Not for smash burgers.', 'Turkey is leaner: add 1 tbsp oil when browning. Cook until no pink remains (75°C).', 'Lighter flavour.', 'No change.', false),
  ('minced turkey', 'minced beef', 'Same weight.', 'Meatballs in sauce.', 'Brown the meatballs, then simmer until cooked through with no pink in the centre (75°C).', 'Richer flavour.', 'No change.', false),
  ('prawns', 'chicken breast', 'Same weight of chicken breast, cut into thin strips.', 'Stir-fries, rice bowls, noodle soups and pasta.', 'Cook the chicken first for 6-8 minutes until cooked through with no pink (75°C), then continue where the recipe adds the prawns. Use a separate board and wash your hands after handling raw chicken.', 'This is an adapted version of the dish.', 'Removes shellfish.', true),
  ('salmon', 'white fish', 'Same weight of white fish fillets.', 'Baked, air-fried or steamed fish.', 'White fillets are thinner: check 2-3 minutes earlier. The fish is done when it is opaque and flakes easily.', 'Milder flavour.', 'Both are fish.', false),
  ('white fish', 'salmon', 'Same weight.', 'Baked fish.', 'Salmon may need 2-4 minutes longer. It is done when it is opaque and flakes easily.', 'Richer flavour.', 'Both are fish.', false),
  ('bacon', 'ham', 'Same weight of cooked ham, diced.', 'Pasta sauces.', 'Ham is already cooked: skip crisping it and just warm it in the pan for 1 minute before adding the pasta.', 'Less smoky and crisp.', 'No change.', false),
  ('ham', 'bacon', 'About 2 rashers per 2 slices of ham.', 'Pasta and toasties.', 'Bacon is raw: chop it and fry until crisp and cooked through before using it where the recipe adds ham.', 'Saltier and smokier.', 'No change.', false),
  ('lemon', 'lime', 'Same amount of juice.', 'Dressings, marinades and finishing squeezes.', 'Use exactly where the recipe uses lemon.', 'Slightly more floral, sharper flavour.', 'No change.', false),
  ('lime', 'lemon', 'Same amount of juice.', 'Dressings, sauces and finishing squeezes.', 'Use exactly where the recipe uses lime.', 'Slightly less aromatic.', 'No change.', false),
  ('honey', 'maple syrup', 'Same amount.', 'Sweetening and glazes.', 'Use exactly where the recipe uses honey.', 'Slightly thinner glaze.', 'No change.', false),
  ('peanut butter', 'tahini', 'Same amount.', 'Savoury nutty sauces.', 'Tahini is more bitter: add ½ tsp honey or sugar and a squeeze of lime, and thin with a little water.', 'Earthier, sesame flavour.', 'Tahini contains sesame, a major allergen. Not a safe swap for anyone allergic to sesame.', false),
  ('curry paste', 'curry powder', '1 tbsp curry powder for every 2 tbsp paste.', 'Curry soups and sauces.', 'Fry the powder in 1 tbsp oil with a little garlic for 30 seconds before adding the liquid.', 'Flavour will differ from a Thai-style paste.', 'Check the label; some blends contain mustard or celery.', true),
  ('curry powder', 'curry paste', '2 tbsp paste for every 1 tbsp powder.', 'Meat curries.', 'Fry the paste for 1 minute; many pastes are salty, so season at the end.', 'Flavour will differ.', 'Many curry pastes contain shrimp or fish; check the label.', false),
  ('mixed berries', 'blueberries', 'Same amount.', 'Yogurt bowls and smoothies.', 'Use exactly where the recipe uses mixed berries.', 'Less tart.', 'No change.', false)
) as v (original, substitute, ratio_note, context_note, adjustment_note, limitation_note, allergen_note, is_adapted)
join public.ingredients o on o.name = v.original
join public.ingredients s on s.name = v.substitute
on conflict (original_ingredient_id, substitute_ingredient_id) do update
  set ratio_note = excluded.ratio_note,
      context_note = excluded.context_note,
      adjustment_note = excluded.adjustment_note,
      limitation_note = excluded.limitation_note,
      allergen_note = excluded.allergen_note,
      is_adapted = excluded.is_adapted;

